const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,PARENT=process.env.PARENT_SHA,PARENT_BLOB=process.env.PARENT_BLOB,TARGET_BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES);const assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[];}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t];}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth});}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context});}}depth+=o-c;while(stack.length&&depth<=stack[stack.length-1].depthBefore){const p=stack.pop();if(p.type==='rule')sel=null;}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d);}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)};}
assert(sh(`git rev-parse ${PARENT}:${TARGET}`)===PARENT_BLOB,'parent blob guard');const parentSrc=cp.execFileSync('git',['show',`${PARENT}:${TARGET}`],{encoding:'utf8'}),p=parse(parentSrc);assert(p.declarations.length===371&&p.dead.length===37,`parent parse ${p.declarations.length}/${p.dead.length}`);assert(new Set(p.dead.map(d=>d.selector)).size===11,'family drift');const identical=p.dead.filter(d=>d.value===d.winnerValue&&d.important===d.winnerImportant).length;assert(identical===14&&p.dead.length-identical===23,'winner identity drift');assert(p.dead.map(d=>d.line).join(',')==='8,9,10,11,12,13,14,15,16,94,95,99,101,187,191,231,248,273,274,427,429,430,435,436,469,470,471,472,473,479,480,486,487,508,550,551,552','dead lines drift');const finalNewline=/\r?\n$/.test(parentSrc),lines=parentSrc.split(/\r?\n/);if(finalNewline&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line))lines.splice(d.line-1,1);const rebuilt=Buffer.from(lines.join('\n')+(finalNewline?'\n':'')),current=fs.readFileSync(TARGET);assert(Buffer.compare(rebuilt,current)===0,'independent reconstruction differs from permanent');const after=parse(current.toString('utf8'));assert(after.declarations.length===334&&after.dead.length===0,`permanent parse ${after.declarations.length}/${after.dead.length}`);const hash=crypto.createHash('sha256').update(current).digest('hex');assert(hash===HASH,`hash drift ${hash}`);assert(current.length===BYTES,`bytes drift ${current.length}`);assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');console.log(`EXACT BYTE IDENTITY PASS|parent=${PARENT}|parentBlob=${PARENT_BLOB}|targetBlob=${TARGET_BLOB}|hash=${hash}|bytes=${current.length}|decl=371->334|dead=37->0|families=11|staticCascadeRows=37|identicalWinners=14|changedWinners=23`);
